// nodePackingAndGPU aggregates Pod requests onto the node that runs them (SCALE-07 / SCALE-08).
//
// Nodes are keyed by cluster + name, the way node_monitoring already keys them: a Pod only ever
// runs on the node of its own cluster, so matching .spec.nodeName across clusters charged one
// cluster's node with another cluster's Pods, and two same-named nodes shared a single row whose
// allocatable came from whichever cluster the inventory listed last.
func nodePackingAndGPU(items []store.K8sInventoryItem) ([]NodePacking, []GPUSummary) {
	gpuKeys := []string{"nvidia.com/gpu", "amd.com/gpu", "intel.com/gpu"}
	type nodeAgg struct {
		clusterID, name  string
		allocCPU, reqCPU int
		allocGPU, reqGPU int
		pods             int
	}
	nodes := map[string]*nodeAgg{}
	for _, it := range items {
		if it.Kind != "Node" {
			continue
		}
		alloc := asAnyMap(it.StatusObject["allocatable"])
		allocGPU := 0
		for _, key := range gpuKeys {
			allocGPU += qtyInt(alloc[key])
		}
		nodes[nodeKey(it.ClusterID, it.Name)] = &nodeAgg{
			clusterID: it.ClusterID,
			name:      it.Name,
			allocCPU:  qtyCPU(alloc["cpu"]),
			allocGPU:  allocGPU,
		}
	}
	for _, it := range items {
		if it.Kind != "Pod" {
			continue
		}
		node := str(it.Spec["nodeName"])
		agg := nodes[nodeKey(it.ClusterID, node)]
		if agg == nil {
			continue
		}
		agg.pods++
		agg.reqCPU += podRequestCPU(it.Spec)
		for _, raw := range podContainers(it.Spec) {
			req := asAnyMap(asAnyMap(asAnyMap(raw)["resources"])["requests"])
			for _, key := range gpuKeys {
				agg.reqGPU += qtyInt(req[key])
			}
		}
	}
	packing := []NodePacking{}
	gpu := []GPUSummary{}
	for _, agg := range nodes {
		pct := 0
		if agg.allocCPU > 0 {
			pct = agg.reqCPU * 100 / agg.allocCPU
		}
		packing = append(packing, NodePacking{ClusterID: agg.clusterID, Node: agg.name, Pods: agg.pods, AllocCPU: agg.allocCPU, ReqCPU: agg.reqCPU, CPUPct: pct})
		if agg.allocGPU > 0 || agg.reqGPU > 0 {
			gpu = append(gpu, GPUSummary{ClusterID: agg.clusterID, Node: agg.name, Allocatable: agg.allocGPU, Requested: agg.reqGPU, Idle: agg.allocGPU - agg.reqGPU})
		}
	}
	// Map iteration order is random, so both tables reshuffled on every request.
	sort.SliceStable(packing, func(i, j int) bool {
		if packing[i].ClusterID != packing[j].ClusterID {
			return packing[i].ClusterID < packing[j].ClusterID
		}
		return packing[i].Node < packing[j].Node
	})
	sort.SliceStable(gpu, func(i, j int) bool {
		if gpu[i].ClusterID != gpu[j].ClusterID {
			return gpu[i].ClusterID < gpu[j].ClusterID
		}
		return gpu[i].Node < gpu[j].Node
	})
	return packing, gpu
}

// --- pod request extraction ---

func podContainers(spec map[string]any) []any {
	ps := spec
	if tmpl := asAnyMap(spec["template"]); tmpl != nil {
		if inner := asAnyMap(tmpl["spec"]); inner != nil {
			ps = inner
		}
	}
	return append(asAnySlice(ps["containers"]), asAnySlice(ps["initContainers"])...)
}

func podRequestCPU(spec map[string]any) int {
	total := 0
	for _, raw := range podContainers(spec) {
		req := asAnyMap(asAnyMap(asAnyMap(raw)["resources"])["requests"])
		total += qtyCPU(req["cpu"])
	}
	return total
}

func podRequestMemBytes(spec map[string]any) int64 {
	var total int64
	for _, raw := range podContainers(spec) {
		req := asAnyMap(asAnyMap(asAnyMap(raw)["resources"])["requests"])
		total += qtyMem(req["memory"])
	}
	return total
}

// qtyMem parses a Kubernetes memory quantity (e.g. "256Mi", "1Gi", 1048576) into bytes.
func qtyMem(v any) int64 {
	switch t := v.(type) {
	case float64:
		return int64(t)
	case string:
		s := strings.TrimSpace(t)
		if s == "" {
			return 0
		}
		units := []struct {
			suf string
			mul int64
		}{{"Ki", 1 << 10}, {"Mi", 1 << 20}, {"Gi", 1 << 30}, {"Ti", 1 << 40}, {"K", 1000}, {"M", 1000 * 1000}, {"G", 1000 * 1000 * 1000}}
		for _, u := range units {
			if strings.HasSuffix(s, u.suf) {
				f, _ := strconv.ParseFloat(strings.TrimSuffix(s, u.suf), 64)
				return int64(f * float64(u.mul))
			}
		}
		f, _ := strconv.ParseFloat(s, 64)
		return int64(f)
	}
	return 0
}

func podRequestGPU(spec map[string]any) int {
	total := 0
	for _, raw := range podContainers(spec) {
		req := asAnyMap(asAnyMap(asAnyMap(raw)["resources"])["requests"])
		total += qtyInt(req["nvidia.com/gpu"])
	}
	return total
}

