	}
	if ownerQuery := strings.ToLower(strings.TrimSpace(f.OwnerQuery)); ownerQuery != "" {
		ownerText := `lower(
			COALESCE(o.team,'') || ' ' || COALESCE(o.owner,'') || ' ' || COALESCE(o.service_name,'') || ' ' ||
