// withAdminAccessUX performs the common admin authorization before individual handlers. Besides
// removing 401/403 ambiguity, a direct browser visit to an API path is redirected back into the
// SPA's access-denied screen instead of rendering raw JSON as a document.
func (s *Server) withAdminAccessUX(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Browser <script> and <link> requests cannot attach the SPA's Bearer token.
		// These are immutable, embedded, non-secret static files and must remain
		// reachable before login so the admin shell can bootstrap.
		if strings.HasPrefix(r.URL.Path, "/admin/assets/xterm/") {
			next.ServeHTTP(w, r)
			return
		}
		// Browser WebSocket constructors cannot attach an Authorization header. The
		// preceding authenticated POST issues a short-lived, one-use ticket; consume
		// it here so the common admin gate does not reject the upgrade before the
		// terminal handler can validate it.
		if sessionID, ok := terminalStreamSessionID(r); ok {
			if auth, valid := s.consumeTerminalTicket(r, sessionID, r.URL.Query().Get("ticket")); valid {
				next.ServeHTTP(w, withTerminalStreamAuth(r, auth))
				return
			}
		}
		// Agent ingestion uses a cluster-scoped token validated after decoding the batch.
		// It must not pass through the interactive administrator authentication gate.
		if r.URL.Path == "/admin/k8s/agent/events" {
			next.ServeHTTP(w, r)
			return
		}
		// CI scanners use a narrowly-scoped API key rather than an interactive admin session.
		// The handlers authenticate security:scan and preserve normal admin access for UI calls.
		if r.Method == http.MethodPost && (r.URL.Path == "/admin/k8s/security/scans/import" || r.URL.Path == "/admin/k8s/security/sboms") {
			next.ServeHTTP(w, r)
			return
		}
		if !strings.HasPrefix(r.URL.Path, "/admin/") || r.URL.Path == "/admin/" {
			next.ServeHTTP(w, r)
			return
		}
		decision := s.evaluateAdminAccess(r)
		if decision.Allowed {
			next.ServeHTTP(w, r)
			return
		}
		s.recordAdminAccessDenied(r, decision)
		status := http.StatusUnauthorized
		code, message := "authentication_required", "관리자 인증이 필요합니다."
		if decision.Authenticated {
			status = http.StatusForbidden
